mapper.sql:
LEFT JOIN simulator_run_record r ON r.id = (
    SELECT MAX(rr.id) FROM simulator_run_record rr WHERE rr.source_id = s.id
)

mapper.select:
SELECT source_id, input_frame_length, transport_header_length, telemetry_header_length,
       custom_data_length, transport_header, custom_data, ver, mid, sid, did, bid, initial_no, flag
FROM simulator_pdxp_config WHERE source_id = #{id}

mapper.update:
UPDATE simulator_pdxp_config SET input_frame_length = #{inputFrameLength},
    transport_header_length = #{transportHeaderLength}, telemetry_header_length = #{telemetryHeaderLength},
    custom_data_length = #{customDataLength}, transport_header = #{transportHeader},
    custom_data = #{customData}, ver = #{ver}, mid = #{mid}, sid = #{sid}, did = #{did},
    bid = #{bid}, initial_no = #{initialNo}, flag = #{flag}
WHERE source_id = #{sourceId}

mapper.select:
SELECT , r.id AS latest_run_id,
       r.run_status AS latest_status, COALESCE(r.sent_unit_count, 0) AS sent_unit_count
FROM simulator_source_config s 


    s.is_deleted = 0



        AND s.source_name LIKE #{namePattern}


        AND COALESCE(r.run_status, 0) = #{status}


ORDER BY s.id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(s.id) FROM simulator_source_config s 


    s.is_deleted = 0



        AND s.source_name LIKE #{namePattern}


        AND COALESCE(r.run_status, 0) = #{status}
